import os,re,collections
root='AlgebraicJacobian.lean'
def mod2path(m):
    return m.replace('.','/')+'.lean'
def imports(p):
    out=[]
    try:
        with open(p) as f:
            for line in f:
                s=line.strip()
                if s.startswith('import '):
                    out.append(s.split()[1])
                elif s and not s.startswith('--') and not s.startswith('/-') and not s.startswith('#'):
                    if s.startswith('import'): continue
    except FileNotFoundError: pass
    return out
seen=set(); stack=[m for m in imports(root) if m.startswith('AlgebraicJacobian')]
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    for n in imports(mod2path(m)):
        if n.startswith('AlgebraicJacobian') and n not in seen: stack.append(n)
allf=[]
for d,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'): allf.append(os.path.join(d,f))
mods={p[:-5].replace('/','.') for p in allf}
unreach=sorted(mods-seen)
print('total files',len(allf),'reachable',len(seen&mods),'unreachable',len(unreach))
